package com.example.data

object CatechismPart1 {
    fun getArticles(): List<CatechismArticle> {
        val list = mutableListOf<CatechismArticle>()

        // -------------------------------------------------------------------
        // SECTION 1: FAITH, GOD, CREATION & THE APOSTLES' CREED (Q1 - Q90)
        // -------------------------------------------------------------------
        
        // Q1 - Q10: Purpose of Man, Knowledge of God, Divine Revelation
        list.add(CatechismArticle("cat_001", "Faith & Creed", "Q. 1", "Who made you?", "Who made you?", "God made me.", "Penny Catechism Q.1", "made, god, creator"))
        list.add(CatechismArticle("cat_002", "Faith & Creed", "Q. 2", "Why did God make you?", "Why did God make you?", "God made me to know Him, to love Him, and to serve Him in this world, and to be happy with Him forever in the next.", "Penny Catechism Q.2; Baltimore Catechism Q.3", "purpose, know, love, serve, heaven, happiness"))
        list.add(CatechismArticle("cat_003", "Faith & Creed", "Q. 3", "To whose image and likeness did God make you?", "To whose image and likeness did God make you?", "God made me to His own image and likeness.", "Genesis 1:26-27; Penny Catechism Q.3", "image, likeness, god, soul"))
        list.add(CatechismArticle("cat_004", "Faith & Creed", "Q. 4", "How is your soul like to God?", "How is your soul like to God?", "My soul is like to God because it is a spirit, which has understanding and free will, and can never die.", "Penny Catechism Q.4; Council of Trent", "soul, spirit, understanding, free will, immortal"))
        list.add(CatechismArticle("cat_005", "Faith & Creed", "Q. 5", "In order to save your soul, what must you do?", "In order to save your soul, what must you do?", "In order to save my soul, I must worship God by faith, hope, and charity; that is, I must believe in Him, hope in Him, and love Him with all my heart.", "Penny Catechism Q.5; Mark 16:16", "salvation, soul, worship, faith, hope, charity"))
        list.add(CatechismArticle("cat_006", "Faith & Creed", "Q. 6", "What is Faith?", "What is Faith?", "Faith is a supernatural virtue by which we firmly believe all the truths which God has revealed, on the authority of God Himself who reveals them, who can neither deceive nor be deceived.", "Vatican I, Sess. 3; Penny Catechism Q.6", "faith, virtue, revelation, truth, divine authority"))
        list.add(CatechismArticle("cat_007", "Faith & Creed", "Q. 7", "Where are these revealed truths contained?", "Where are these revealed truths contained?", "These revealed truths are contained in Holy Scripture (the Bible) and Divine Tradition, as preserved and proposed for our belief by the Catholic Church.", "Council of Trent, Sess. 4; Vatican I", "scripture, tradition, church, revelation, bible"))
        list.add(CatechismArticle("cat_008", "Faith & Creed", "Q. 8", "Can you know God by human reason alone?", "Can you know God by human reason alone?", "Yes, by human reason alone we can know with certainty that God exists as Creator of all things; but to know His divine mysteries we need Supernatural Revelation.", "Vatican I, Sess. 3, Canon 1; Romans 1:20", "reason, existence, creator, revelation, natural law"))
        list.add(CatechismArticle("cat_009", "Faith & Creed", "Q. 9", "How do we know what God has revealed?", "How do we know what God has revealed?", "We know what God has revealed by the testimony and infallible teaching of the Holy Catholic Church.", "Vatican I, Sess. 3; Penny Catechism Q.9", "church, magisterium, infallibility, revelation"))
        list.add(CatechismArticle("cat_010", "Faith & Creed", "Q. 10", "What summary of belief contains the chief truths of Faith?", "What summary of belief contains the chief truths of Faith?", "The chief truths of Faith are summarized in the Apostles' Creed.", "Penny Catechism Q.10; Catechism of Trent", "apostles creed, summary, truths, faith"))

        // Q11 - Q20: The Apostles' Creed Structure & First Article (God the Father Almighty)
        list.add(CatechismArticle("cat_011", "Faith & Creed", "Q. 11", "Recite the Apostles' Creed", "What is the text of the Apostles' Creed?", "I believe in God, the Father Almighty, Creator of heaven and earth; and in Jesus Christ, His only Son, Our Lord; who was conceived by the Holy Ghost, born of the Virgin Mary, suffered under Pontius Pilate, was crucified, died, and was buried; He descended into hell; the third day He rose again from the dead; He ascended into heaven, sitteth at the right hand of God the Father Almighty; from thence He shall come to judge the living and the dead. I believe in the Holy Ghost, the Holy Catholic Church, the communion of saints, the forgiveness of sins, the resurrection of the body, and life everlasting. Amen.", "Traditional Apostles' Creed", "creed, text, apostles, articles"))
        list.add(CatechismArticle("cat_012", "Faith & Creed", "Q. 12", "How many articles are there in the Apostles' Creed?", "How many articles are there in the Apostles' Creed?", "There are twelve articles in the Apostles' Creed.", "Penny Catechism Q.12", "twelve articles, creed, structure"))
        list.add(CatechismArticle("cat_013", "Faith & Creed", "Q. 13", "What is the first article of the Creed?", "What is the first article of the Creed?", "The first article of the Creed is: 'I believe in God, the Father Almighty, Creator of heaven and earth.'", "Penny Catechism Q.13", "first article, god, father, almighty, creator"))
        list.add(CatechismArticle("cat_014", "Faith & Creed", "Q. 14", "What is God?", "What is God?", "God is the supreme Spirit, who alone exists of Himself, and is infinitely perfect, all-good, all-powerful, and eternal.", "Penny Catechism Q.14; Council of Trent", "god, spirit, supreme, perfect, eternal, infinite"))
        list.add(CatechismArticle("cat_015", "Faith & Creed", "Q. 15", "Why is God called 'Almighty'?", "Why is God called 'Almighty'?", "God is called 'Almighty' because He can do all things: 'With God all things are possible' (Matthew 19:26).", "Penny Catechism Q.15; Matthew 19:26", "almighty, omnipotent, power, god"))
        list.add(CatechismArticle("cat_016", "Faith & Creed", "Q. 16", "Why is God called 'Creator of heaven and earth'?", "Why is God called 'Creator of heaven and earth'?", "God is called Creator of heaven and earth because He made heaven and earth, and all things out of nothing, by His almighty word.", "Genesis 1:1; IV Lateran Council (1215); Penny Catechism Q.16", "creator, creation, ex nihilo, heaven, earth"))
        list.add(CatechismArticle("cat_017", "Faith & Creed", "Q. 17", "Had God any beginning?", "Had God any beginning?", "No, God had no beginning: He always was, He is, and He always will be eternal.", "Psalm 89:2; Penny Catechism Q.17", "eternal, beginning, end, god"))
        list.add(CatechismArticle("cat_018", "Faith & Creed", "Q. 18", "Where is God?", "Where is God?", "God is everywhere—in heaven, on earth, and in all places.", "Psalm 138:7-10; Penny Catechism Q.18", "omnipresent, everywhere, heaven, earth"))
        list.add(CatechismArticle("cat_019", "Faith & Creed", "Q. 19", "Does God know and see all things?", "Does God know and see all things?", "Yes, God knows and sees all things, even our most secret thoughts, desires, and actions.", "Hebrews 4:13; Penny Catechism Q.19", "omniscient, know, see, thoughts, heart"))
        list.add(CatechismArticle("cat_020", "Faith & Creed", "Q. 20", "Has God a body?", "Has God a body?", "No, God has no body; He is a pure spirit. But in the Incarnation, the Divine Son took a human body and soul.", "John 4:24; Penny Catechism Q.20", "spirit, no body, god, divine nature"))

        // Q21 - Q30: The Holy Trinity
        list.add(CatechismArticle("cat_021", "Faith & Creed", "Q. 21", "Is there only one God?", "Is there only one God?", "Yes, there is only one God.", "Deuteronomy 6:4; Penny Catechism Q.21", "one god, monotheism, divine essence"))
        list.add(CatechismArticle("cat_022", "Faith & Creed", "Q. 22", "How many Persons are there in God?", "How many Persons are there in God?", "In God there are Three Divine Persons: God the Father, God the Son, and God the Holy Ghost.", "Matthew 28:19; Penny Catechism Q.22", "three persons, trinity, father, son, holy ghost"))
        list.add(CatechismArticle("cat_023", "Faith & Creed", "Q. 23", "Are these Three Persons three Gods?", "Are these Three Persons three Gods?", "No, these Three Persons are not three Gods, but One and the same God.", "Council of Florence; Athanasian Creed; Penny Catechism Q.23", "trinity, one god, divine nature, co-equal"))
        list.add(CatechismArticle("cat_024", "Faith & Creed", "Q. 24", "Is the Father God?", "Is the Father God?", "Yes, God the Father is true God.", "Penny Catechism Q.24", "father, true god, first person"))
        list.add(CatechismArticle("cat_025", "Faith & Creed", "Q. 25", "Is the Son God?", "Is the Son God?", "Yes, God the Son is true God.", "Penny Catechism Q.25; John 1:1", "son, true god, second person, word"))
        list.add(CatechismArticle("cat_026", "Faith & Creed", "Q. 26", "Is the Holy Ghost God?", "Is the Holy Ghost God?", "Yes, God the Holy Ghost is true God.", "Penny Catechism Q.26; Acts 5:3-4", "holy ghost, true god, third person"))
        list.add(CatechismArticle("cat_027", "Faith & Creed", "Q. 27", "What is this mystery called?", "What is this mystery called?", "This mystery is called the Mystery of the Blessed Trinity.", "Penny Catechism Q.27", "blessed trinity, mystery, doctrine"))
        list.add(CatechismArticle("cat_028", "Faith & Creed", "Q. 28", "Is any one of the Three Persons older or greater than the others?", "Is any one of the Three Persons older or greater than the others?", "No, none of the Three Persons is older, greater, or less than the others; all Three Persons are co-equal, co-eternal, and equal in all perfections.", "Athanasian Creed; Penny Catechism Q.28", "co-equal, co-eternal, equality, trinity"))
        list.add(CatechismArticle("cat_029", "Faith & Creed", "Q. 29", "Can we fully understand the Mystery of the Blessed Trinity?", "Can we fully understand the Mystery of the Blessed Trinity?", "No, we cannot fully understand it in this life, because it is a divine mystery that surpasses human understanding.", "Vatican I, Sess. 3; Penny Catechism Q.29", "mystery, understanding, faith, trinity"))
        list.add(CatechismArticle("cat_030", "Faith & Creed", "Q. 30", "Who created the Angels?", "Who created the Angels?", "God created the Angels as pure spiritual beings, endowed with intelligence and free will.", "Colossians 1:16; IV Lateran Council; Penny Catechism Q.30", "angels, creation, spirits, intelligence"))

        // Q31 - Q40: Angels, Devils, Fall of Man & Original Sin
        list.add(CatechismArticle("cat_031", "Faith & Creed", "Q. 31", "Did all the Angels remain faithful to God?", "Did all the Angels remain faithful to God?", "No, many Angels rebelled through pride under Lucifer, were cast out of Heaven, and became devils in Hell.", "2 Peter 2:4; Apocalypse 12:7-9; Penny Catechism Q.31", "angels, fallen, devils, lucifer, pride, hell"))
        list.add(CatechismArticle("cat_032", "Faith & Creed", "Q. 32", "What do the good Angels do for us?", "What do the good Angels do for us?", "The good Angels praise God in Heaven, intercede for us, and protect us on earth as our Guardian Angels.", "Psalm 90:11-12; Matthew 18:10; Penny Catechism Q.32", "guardian angels, protection, intercession, heaven"))
        list.add(CatechismArticle("cat_033", "Faith & Creed", "Q. 33", "Who were our first parents?", "Who were our first parents?", "Our first parents were Adam and Eve, created directly by God in the state of innocence and original justice.", "Genesis 1:27; Genesis 2:7; Penny Catechism Q.33", "adam, eve, first parents, original justice"))
        list.add(CatechismArticle("cat_034", "Faith & Creed", "Q. 34", "Where did God place Adam and Eve?", "Where did God place Adam and Eve?", "God placed Adam and Eve in the Garden of Paradise (Eden).", "Genesis 2:8; Penny Catechism Q.34", "paradise, eden, innocence, genesis"))
        list.add(CatechismArticle("cat_035", "Faith & Creed", "Q. 35", "Did Adam and Eve remain faithful to God?", "Did Adam and Eve remain faithful to God?", "No, Adam and Eve disobeyed God's command by eating the forbidden fruit at the instigation of the devil.", "Genesis 3:1-6; Penny Catechism Q.35", "disobedience, fall, forbidden fruit, devil"))
        list.add(CatechismArticle("cat_036", "Faith & Creed", "Q. 36", "What happened to Adam and Eve after their sin?", "What happened to Adam and Eve after their sin?", "Adam and Eve lost sanctifying grace, were cast out of Paradise, became subject to suffering and death, and forfeited their right to Heaven.", "Genesis 3:16-24; Council of Trent, Sess. 5; Penny Catechism Q.36", "fall, penalty, suffering, death, lost grace"))
        list.add(CatechismArticle("cat_037", "Faith & Creed", "Q. 37", "Is Adam's sin passed down to all mankind?", "Is Adam's sin passed down to all mankind?", "Yes, Adam's sin is transmitted to all his descendants by natural propagation; this inherited sin is called Original Sin.", "Council of Trent, Sess. 5 (1546); Romans 5:12; Penny Catechism Q.37", "original sin, adam, transmission, propagation, council of trent"))
        list.add(CatechismArticle("cat_038", "Faith & Creed", "Q. 38", "Was any human person preserved from Original Sin?", "Was any human person preserved from Original Sin?", "Yes, the Blessed Virgin Mary was preserved immune from all stain of Original Sin from the first moment of her Conception, by a singular privilege of Almighty God (The Immaculate Conception).", "Dogma defined by Pope Pius IX, Ineffabilis Deus (1854); Luke 1:28", "immaculate conception, mary, virgin mary, pius ix, preserved from sin"))
        list.add(CatechismArticle("cat_039", "Faith & Creed", "Q. 39", "Did God abandon mankind after the fall?", "Did God abandon mankind after the fall?", "No, God immediately promised a Redeemer to save fallen mankind from sin and hell.", "Genesis 3:15; Penny Catechism Q.39", "redeemer, promise, genesis 3:15, salvation"))
        list.add(CatechismArticle("cat_040", "Faith & Creed", "Q. 40", "Who is the Redeemer of mankind?", "Who is the Redeemer of mankind?", "Our Lord Jesus Christ is the Redeemer of mankind.", "Penny Catechism Q.40; Acts 4:12", "jesus christ, redeemer, lord, savior"))

        // Q41 - Q50: Second Article of the Creed & Incarnation
        list.add(CatechismArticle("cat_041", "Faith & Creed", "Q. 41", "What is the second article of the Creed?", "What is the second article of the Creed?", "The second article of the Creed is: 'And in Jesus Christ, His only Son, Our Lord.'", "Penny Catechism Q.41", "second article, jesus christ, son of god, our lord"))
        list.add(CatechismArticle("cat_042", "Faith & Creed", "Q. 42", "What does the name 'Jesus' mean?", "What does the name 'Jesus' mean?", "The name 'Jesus' means 'Savior', because He saves us from our sins.", "Matthew 1:21; Penny Catechism Q.42", "jesus, savior, name, salvation"))
        list.add(CatechismArticle("cat_043", "Faith & Creed", "Q. 43", "What does the word 'Christ' mean?", "What does the word 'Christ' mean?", "The word 'Christ' means 'Anointed', showing that He is the supreme Priest, Prophet, and King.", "Penny Catechism Q.43; Psalm 44:8", "christ, anointed, priest, prophet, king"))
        list.add(CatechismArticle("cat_044", "Faith & Creed", "Q. 44", "Is Jesus Christ God, or man, or both?", "Is Jesus Christ God, or man, or both?", "Jesus Christ is true God and true Man.", "Council of Chalcedon (451); Penny Catechism Q.44", "true god, true man, divine and human, chalcedon"))
        list.add(CatechismArticle("cat_045", "Faith & Creed", "Q. 45", "How many Natures are there in Jesus Christ?", "How many Natures are there in Jesus Christ?", "There are two Natures in Jesus Christ: the Divine Nature and the Human Nature.", "Council of Chalcedon (451); Penny Catechism Q.45", "two natures, divine nature, human nature"))
        list.add(CatechismArticle("cat_046", "Faith & Creed", "Q. 46", "How many Persons are there in Jesus Christ?", "How many Persons are there in Jesus Christ?", "There is only One Divine Person in Jesus Christ—the Second Person of the Most Holy Trinity.", "Council of Ephesus (431); Council of Chalcedon; Penny Catechism Q.46", "one person, divine person, hypostatic union"))
        list.add(CatechismArticle("cat_047", "Faith & Creed", "Q. 47", "What is the mystery of God taking human nature called?", "What is the mystery of God taking human nature called?", "The mystery of God taking human nature is called the Incarnation.", "John 1:14; Penny Catechism Q.47", "incarnation, mystery, word made flesh"))
        list.add(CatechismArticle("cat_048", "Faith & Creed", "Q. 48", "What is the third article of the Creed?", "What is the third article of the Creed?", "The third article of the Creed is: 'Who was conceived by the Holy Ghost, born of the Virgin Mary.'", "Penny Catechism Q.48", "third article, conceived, holy ghost, born, virgin mary"))
        list.add(CatechismArticle("cat_049", "Faith & Creed", "Q. 49", "Had Jesus Christ any human father?", "Had Jesus Christ any human father?", "No, Jesus Christ had no human father; St. Joseph was His foster-father and legal guardian.", "Luke 1:34-35; Matthew 1:20; Penny Catechism Q.49", "no human father, virgin birth, st joseph, foster father"))
        list.add(CatechismArticle("cat_050", "Faith & Creed", "Q. 50", "Was Mary always a Virgin?", "Was Mary always a Virgin?", "Yes, Mary was a Virgin before, during, and perpetually after the Birth of Jesus Christ (Perpetual Virginity).", "Lateran Council (649); Council of Constantinople II; Penny Catechism Q.50", "perpetual virginity, mary, virgin, perpetual"))

        // Q51 - Q60: Fourth Article, Passion, Death & Redemptive Sacrifice
        list.add(CatechismArticle("cat_051", "Faith & Creed", "Q. 51", "What is the fourth article of the Creed?", "What is the fourth article of the Creed?", "The fourth article of the Creed is: 'Suffered under Pontius Pilate, was crucified, died, and was buried.'", "Penny Catechism Q.51", "fourth article, suffered, pontius pilate, crucified, died, buried"))
        list.add(CatechismArticle("cat_052", "Faith & Creed", "Q. 52", "Who was Pontius Pilate?", "Who was Pontius Pilate?", "Pontius Pilate was the Roman Governor of Judea who condemned Jesus to death on the Cross.", "Penny Catechism Q.52; Gospels", "pontius pilate, roman governor, condemnation"))
        list.add(CatechismArticle("cat_053", "Faith & Creed", "Q. 53", "On what day did Jesus Christ die?", "On what day did Jesus Christ die?", "Jesus Christ died on Good Friday, at three o'clock in the afternoon, on Mount Calvary.", "Penny Catechism Q.53; Gospels", "good friday, calvary, death, cross"))
        list.add(CatechismArticle("cat_054", "Faith & Creed", "Q. 54", "Why did Jesus Christ suffer and die?", "Why did Jesus Christ suffer and die?", "Jesus Christ suffered and died to satisfy God's justice for our sins, and to open the gates of Heaven for all mankind.", "Council of Trent, Sess. 6; 1 Peter 2:24; Penny Catechism Q.54", "redemption, satisfaction, sacrifice, sins, cross"))
        list.add(CatechismArticle("cat_055", "Faith & Creed", "Q. 55", "Was Christ's sacrifice on the Cross a true propitiation?", "Was Christ's sacrifice on the Cross a true propitiation?", "Yes, Christ's death on the Cross was a true, perfect, and superabundant propitiatory Sacrifice for all sins.", "Council of Trent, Sess. 6 & 22; 1 John 2:2; Penny Catechism Q.55", "propitiation, sacrifice, cross, satisfaction, superabundant"))
        list.add(CatechismArticle("cat_056", "Faith & Creed", "Q. 56", "What is the fifth article of the Creed?", "What is the fifth article of the Creed?", "The fifth article of the Creed is: 'He descended into hell; the third day He rose again from the dead.'", "Penny Catechism Q.56", "fifth article, descended into hell, resurrection, third day"))
        list.add(CatechismArticle("cat_057", "Faith & Creed", "Q. 57", "What place is meant here by 'hell'?", "What place is meant here by 'hell'?", "By 'hell' in this article is meant the Limbo of the Fathers (Limbus Patrum), where the souls of the just who died before Christ were waiting for redemption.", "1 Peter 3:19; Catechism of Trent; Penny Catechism Q.57", "limbo, limbus patrum, fathers, hell, waiting souls"))
        list.add(CatechismArticle("cat_058", "Faith & Creed", "Q. 58", "On what day did Christ rise from the dead?", "On what day did Christ rise from the dead?", "Jesus Christ rose again from the dead on Easter Sunday, the third day after His death.", "Penny Catechism Q.58; 1 Corinthians 15:4", "easter sunday, resurrection, third day, dead"))
        list.add(CatechismArticle("cat_059", "Faith & Creed", "Q. 59", "Did Christ rise by His own power?", "Did Christ rise by His own power?", "Yes, Jesus Christ rose by His own divine power, reuniting His soul to His glorified body.", "John 10:18; Penny Catechism Q.59", "resurrection, divine power, glorified body"))
        list.add(CatechismArticle("cat_060", "Faith & Creed", "Q. 60", "What is the sixth article of the Creed?", "What is the sixth article of the Creed?", "The sixth article of the Creed is: 'He ascended into heaven, sitteth at the right hand of God the Father Almighty.'", "Penny Catechism Q.60", "sixth article, ascension, right hand of god"))

        // Q61 - Q70: Ascension, Judgment, Seventh & Eighth Articles
        list.add(CatechismArticle("cat_061", "Faith & Creed", "Q. 61", "When did Christ ascend into Heaven?", "When did Christ ascend into Heaven?", "Jesus Christ ascended into Heaven forty days after His Resurrection, on Ascension Thursday.", "Acts 1:3-9; Penny Catechism Q.61", "ascension, forty days, ascension thursday"))
        list.add(CatechismArticle("cat_062", "Faith & Creed", "Q. 62", "What is meant by 'sitteth at the right hand of God'?", "What is meant by 'sitteth at the right hand of God'?", "It means that Christ, as God, is equal to the Father; and as Man, holds the highest place of honor and power in Heaven.", "Mark 16:19; Penny Catechism Q.62", "right hand of god, power, glory, honor"))
        list.add(CatechismArticle("cat_063", "Faith & Creed", "Q. 63", "What is the seventh article of the Creed?", "What is the seventh article of the Creed?", "The seventh article of the Creed is: 'From thence He shall come to judge the living and the dead.'", "Penny Catechism Q.63", "seventh article, judge, living and dead, second coming"))
        list.add(CatechismArticle("cat_064", "Faith & Creed", "Q. 64", "When will Christ come again?", "When will Christ come again?", "Christ will come again at the end of the world to judge all mankind in the General Judgment.", "Matthew 25:31-46; Penny Catechism Q.64", "general judgment, second coming, end of world"))
        list.add(CatechismArticle("cat_065", "Faith & Creed", "Q. 65", "What is the Particular Judgment?", "What is the Particular Judgment?", "The Particular Judgment is the judgment passed upon each individual soul immediately after death.", "Hebrews 9:27; Benedictus Deus (1336); Penny Catechism Q.65", "particular judgment, soul, death, judgment"))
        list.add(CatechismArticle("cat_066", "Faith & Creed", "Q. 66", "What is the eighth article of the Creed?", "What is the eighth article of the Creed?", "The eighth article of the Creed is: 'I believe in the Holy Ghost.'", "Penny Catechism Q.66", "eighth article, holy ghost, third person"))
        list.add(CatechismArticle("cat_067", "Faith & Creed", "Q. 67", "Who is the Holy Ghost?", "Who is the Holy Ghost?", "The Holy Ghost is the Third Person of the Blessed Trinity, true God proceeding from the Father and the Son.", "Council of Constantinople I (381); Council of Florence; Penny Catechism Q.67", "holy ghost, procession, father and son, filioque"))
        list.add(CatechismArticle("cat_068", "Faith & Creed", "Q. 68", "When did the Holy Ghost descend upon the Apostles?", "When did the Holy Ghost descend upon the Apostles?", "The Holy Ghost descended upon the Apostles on Whit Sunday (Pentecost), ten days after the Ascension.", "Acts 2:1-4; Penny Catechism Q.68", "pentecost, whit sunday, apostles, descent"))
        list.add(CatechismArticle("cat_069", "Faith & Creed", "Q. 69", "What is the ninth article of the Creed?", "What is the ninth article of the Creed?", "The ninth article of the Creed is: 'The Holy Catholic Church, the communion of saints.'", "Penny Catechism Q.69", "ninth article, catholic church, communion of saints"))
        list.add(CatechismArticle("cat_070", "Faith & Creed", "Q. 70", "What is the Catholic Church?", "What is the Catholic Church?", "The Catholic Church is the union of all faithful Christians baptized in Christ, who profess the true faith, participate in the same Sacraments, and obey their lawful pastors under the supreme authority of the Pope.", "St. Robert Bellarmine; Pope Leo XIII, Satis Cognitum; Penny Catechism Q.70", "catholic church, definition, pope, sacraments, faithful"))

        // Q71 - Q80: Marks & Head of the Church, Infallibility
        list.add(CatechismArticle("cat_071", "Faith & Creed", "Q. 71", "Who is the invisible Head of the Church?", "Who is the invisible Head of the Church?", "Jesus Christ is the invisible Head of the Church.", "Ephesians 1:22-23; Penny Catechism Q.71", "head of church, jesus christ, invisible head"))
        list.add(CatechismArticle("cat_072", "Faith & Creed", "Q. 72", "Who is the visible Head of the Church on earth?", "Who is the visible Head of the Church on earth?", "The Pope (Bishop of Rome), who is the legitimate successor of St. Peter, is the visible Head of the Church on earth and Vicar of Christ.", "Vatican I, Pastor Aeternus; Matthew 16:18-19; Penny Catechism Q.72", "pope, st peter, vicar of christ, visible head"))
        list.add(CatechismArticle("cat_073", "Faith & Creed", "Q. 73", "How many marks are there of the True Church?", "How many marks are there of the True Church?", "There are four marks of the True Church: she is One, Holy, Catholic, and Apostolic.", "Nicene Creed (381); Penny Catechism Q.73", "four marks, one, holy, catholic, apostolic"))
        list.add(CatechismArticle("cat_074", "Faith & Creed", "Q. 74", "Why is the Church One?", "Why is the Church One?", "The Church is One because all her members profess one and the same faith, offer the same Sacrifice of the Mass, receive the same Sacraments, and submit to one supreme Head, the Pope.", "Pope Leo XIII, Satis Cognitum; Penny Catechism Q.74", "one, unity, faith, mass, sacraments, pope"))
        list.add(CatechismArticle("cat_075", "Faith & Creed", "Q. 75", "Why is the Church Holy?", "Why is the Church Holy?", "The Church is Holy because her Founder Jesus Christ is holy, her doctrines and Sacraments lead to holiness, and she produces holy saints in every age.", "Penny Catechism Q.75", "holy, founder, doctrine, sacraments, saints"))
        list.add(CatechismArticle("cat_076", "Faith & Creed", "Q. 76", "Why is the Church Catholic (Universal)?", "Why is the Church Catholic (Universal)?", "The Church is Catholic because she exists for all nations, teaches all revealed truths, and endures through all ages from Christ until the end of time.", "Matthew 28:19-20; Penny Catechism Q.76", "catholic, universal, all nations, all time"))
        list.add(CatechismArticle("cat_077", "Faith & Creed", "Q. 77", "Why is the Church Apostolic?", "Why is the Church Apostolic?", "The Church is Apostolic because she was founded upon the Apostles by Christ, preserves their unchanged doctrine, and derives her hierarchy by unbroken apostolic succession.", "Ephesians 2:20; Penny Catechism Q.77", "apostolic, succession, doctrine, hierarchy"))
        list.add(CatechismArticle("cat_078", "Faith & Creed", "Q. 78", "Can the Catholic Church teach error?", "Can the Catholic Church teach error?", "No, the Catholic Church cannot teach error in faith or morals, because Christ promised that the gates of hell shall never prevail against her, and the Holy Ghost guides her into all truth.", "Infallibility Dogma: Vatican I (1870); Matthew 16:18; John 16:13; Penny Catechism Q.78", "infallibility, error, gates of hell, truth"))
        list.add(CatechismArticle("cat_079", "Faith & Creed", "Q. 79", "What is Papal Infallibility?", "What is Papal Infallibility?", "Papal Infallibility is the charisma promised by Christ whereby the Pope cannot err when he defines Ex-Cathedra a doctrine regarding faith or morals to be held by the Universal Church.", "Vatican Council I (1870), Pastor Aeternus, Cap. 4", "papal infallibility, ex-cathedra, dogma, vatican i"))
        list.add(CatechismArticle("cat_080", "Faith & Creed", "Q. 80", "Is there salvation outside the Catholic Church?", "Is there salvation outside the Catholic Church?", "No. It is an infallibly defined dogma that outside the Catholic Church there is no salvation ('Extra Ecclesiam Nulla Salus'). All who die outside the true fold cannot be saved.", "Ex-Cathedra Definitions: IV Lateran (1215); Unam Sanctam (1302); Council of Florence (1442)", "extra ecclesiam nulla salus, dogma, salvation, outside church no salvation"))

        // Q81 - Q90: Communion of Saints, Tenth, Eleventh & Twelfth Articles
        list.add(CatechismArticle("cat_081", "Faith & Creed", "Q. 81", "What is the Communion of Saints?", "What is the Communion of Saints?", "The Communion of Saints is the spiritual union and sharing of spiritual goods among the members of the Church Triumphant in Heaven, the Church Suffering in Purgatory, and the Church Militant on earth.", "Catechism of Trent; Penny Catechism Q.81", "communion of saints, militant, suffering, triumphant"))
        list.add(CatechismArticle("cat_082", "Faith & Creed", "Q. 82", "What is Purgatory?", "What is Purgatory?", "Purgatory is the state of temporary suffering after death where souls who die in sanctifying grace are purified from venial sins and temporal punishment due to remitted mortal sins before entering Heaven.", "Council of Trent, Sess. 25 (1563); 2 Machabees 12:46; Penny Catechism Q.82", "purgatory, purification, temporal punishment, suffering"))
        list.add(CatechismArticle("cat_083", "Faith & Creed", "Q. 83", "Can we help the souls in Purgatory?", "Can we help the souls in Purgatory?", "Yes, we can help the Holy Souls in Purgatory by our prayers, indulgences, alms, good works, and above all by offering the Holy Sacrifice of the Mass for them.", "Council of Trent, Sess. 25; Penny Catechism Q.83", "holy souls, purgatory, mass, indulgences, prayer"))
        list.add(CatechismArticle("cat_084", "Faith & Creed", "Q. 84", "What is the tenth article of the Creed?", "What is the tenth article of the Creed?", "The tenth article of the Creed is: 'The forgiveness of sins.'", "Penny Catechism Q.84", "tenth article, forgiveness of sins, absolution"))
        list.add(CatechismArticle("cat_085", "Faith & Creed", "Q. 85", "How are sins forgiven in the Catholic Church?", "How are sins forgiven in the Catholic Church?", "Original sin is forgiven by Water Baptism; actual sins committed after Baptism are forgiven through the Sacrament of Penance (Holy Confession).", "Council of Trent, Sess. 7 & 14; Penny Catechism Q.85", "forgiveness, baptism, penance, confession"))
        list.add(CatechismArticle("cat_086", "Faith & Creed", "Q. 86", "What is the eleventh article of the Creed?", "What is the eleventh article of the Creed?", "The eleventh article of the Creed is: 'The resurrection of the body.'", "Penny Catechism Q.86", "eleventh article, resurrection of body, last day"))
        list.add(CatechismArticle("cat_087", "Faith & Creed", "Q. 87", "What is meant by the resurrection of the body?", "What is meant by the resurrection of the body?", "It means that on the Last Day the bodies of all men will rise from the dead and be reunited with their souls forever.", "1 Corinthians 15:52-53; Penny Catechism Q.87", "resurrection, body, last day, soul"))
        list.add(CatechismArticle("cat_088", "Faith & Creed", "Q. 88", "What is the twelfth article of the Creed?", "What is the twelfth article of the Creed?", "The twelfth article of the Creed is: 'And life everlasting. Amen.'", "Penny Catechism Q.88", "twelfth article, life everlasting, heaven, amen"))
        list.add(CatechismArticle("cat_089", "Faith & Creed", "Q. 89", "What is life everlasting?", "What is life everlasting?", "Life everlasting is the eternal happiness of Heaven for the righteous, enjoying the Beatific Vision of God face to face forever.", "Council of Florence; Benedictus Deus; Penny Catechism Q.89", "life everlasting, beatific vision, heaven, eternal happiness"))
        list.add(CatechismArticle("cat_090", "Faith & Creed", "Q. 90", "What will happen to the wicked who die in unrepented mortal sin?", "What will happen to the wicked who die in unrepented mortal sin?", "The wicked who die in unrepented mortal sin or outside the Catholic Faith will go into everlasting fire in Hell, to be tormented with the devils forever.", "Dogma defined by IV Lateran (1215); Matthew 25:41,46; Penny Catechism Q.90", "hell, damnation, eternal fire, mortal sin, wicked"))

        return list
    }
}
